def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > 0:
                    dangerous_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    low_supply = supply <= 17.0
    high_supply = supply >= 22.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if low_supply:
        urgency += 2
    if day >= 8:
        urgency += 1

    highest_prev = max(dangerous_prev) if dangerous_prev else 0.0
    moderate_prev = 0.0
    for b in dangerous_prev:
        if b <= 90.0 and b > moderate_prev:
            moderate_prev = b

    if urgency >= 7:
        target = 92.0
        if highest_prev > 0 and highest_prev < 95.0:
            target = max(target, highest_prev + 2.0)
    elif urgency >= 4:
        if moderate_prev > 0:
            target = max(52.0, moderate_prev + 1.5)
        else:
            target = 58.0 if low_supply else 46.0
    else:
        if highest_prev >= 120.0:
            target = 8.0 if high_supply else 14.0
        elif highest_prev >= 85.0:
            target = 16.0 if high_supply else 24.0
        elif moderate_prev > 0:
            target = min(60.0, moderate_prev + 1.0)
        else:
            target = 22.0 if low_supply else 15.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0 and day <= 7:
        reserve = 20.0
    elif hp > 2 and day <= 8:
        reserve = 10.0

    affordable = max(0.0, budget - reserve)
    bid = min(target, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 88.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, 55.0 if not low_supply else 65.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = float(budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        cap = my_budget if my_budget > 0 else DAILY_SALARY
        return float(min(cap, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday bids
    yesterday_bids = []
    yesterday_pressured = []  # (opp_id, bid) for those with high bid
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            b = float(b)
        except Exception:
            continue
        yesterday_bids.append(b)
        if b >= DAILY_SALARY * 0.85:
            yesterday_pressured.append((oid, b))

    # Supply pressure: when supply is tight, increase bid to avoid being outbid.
    # supply in [15,25]; map to a multiplier in [1.25, 0.85]
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        tightness = 0.5
    tightness = max(0.0, min(1.0, float(tightness)))
    supply_mult = 1.25 - 0.4 * tightness  # tighter supply => higher mult

    # If we are in danger, bid more aggressively.
    danger = 0
    if my_hp <= 2:
        danger = 2
    elif my_hp <= 4:
        danger = 1
    if my_no_water_days >= 2:
        danger = max(danger, 1)

    # Base bid from yesterday's observed market.
    if yesterday_bids:
        top_bid = max(yesterday_bids)
        avg_bid = sum(yesterday_bids) / float(len(yesterday_bids))

        if yesterday_pressured:
            # High-bid cluster: try to be competitive but not necessarily match the max.
            target = min(top_bid * 0.92, avg_bid * 1.05)
        else:
            # No extreme bids: bid near average.
            target = avg_bid * 0.95

        # Adjust by supply and our danger.
        if danger == 2:
            target *= 1.25
        elif danger == 1:
            target *= 1.10

        target *= supply_mult
    else:
        # No trace bids available: conservative
        target = DAILY_SALARY * (0.55 + 0.15 * tightness)
        if danger == 2:
            target *= 1.25
        elif danger == 1:
            target *= 1.10

    # Convert target to a safe cap based on budget.
    # Ensure some chance to win while not going bankrupt.
    if my_budget <= 0:
        # If no budget, still try to bid small (game may allow negative/zero; keep safe)
        return 0.0

    # Keep reserve: don't spend more than ~70% of current budget unless very dangerous.
    spend_frac = 0.7 if danger == 0 else (0.85 if danger == 1 else 0.95)
    cap = my_budget * spend_frac

    # Also avoid bidding above a reasonable fraction of supply*WATER_REQ scaling.
    # (Heuristic cap)
    heuristic_cap = DAILY_SALARY * (0.9 + 0.2 * tightness)

    bid = float(min(target, cap, heuristic_cap, my_budget))

    # Final guard: bid at least a small amount to avoid always losing.
    min_bid = DAILY_SALARY * 0.35
    if bid < min_bid:
        bid = float(min(my_budget, min_bid))

    return float(bid)

